const mk=s=>`<mark>${s}</mark>`;
const hexLum=hex=>{const c=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.03928?v/12.92:((v+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2]};
const inkFor=hex=>{const l=hexLum(hex);return (l+.05)/.07>1.05/(l+.05)?'#0f172a':'#f1f5f9'};
const stripPrefix=html=>html.replace(/^<strong>(洞察：|Insight:)<\/strong>\s*/,'');
const markEvidence=html=>html.replace(/[（(]\s*[\d.]+%[^（()）]*[）)]/g,m=>`<span class="ev">${m}</span>`);
const insightBlock=(html,label)=>html?`<aside class="insight"><span class="insight-label">${label||text(bi('洞察','Insight'))}</span><p>${markEvidence(html)}</p></aside>`:'';
